%% stem_05_cutoff_convergence.m - NiCl2 plane-wave cutoff convergence
% Generated by tools/matlab/make_stem.py from s11_results.json -> convergence. Values: [SIMULATED].
% Runs in MATLAB R2019b+ and GNU Octave 8+. Output: out/stem_05_cutoff_convergence.png
if exist('OCTAVE_VERSION', 'builtin'), graphics_toolkit('gnuplot'); end   % Octave only; MATLAB skips this line
fig = figure('Visible', 'off', 'Color', 'w', 'Position', [100 100 960 520]);
set(fig, 'PaperPositionMode', 'auto');
hold on; grid on; box off;
try, set(gca, 'GridColor', [0.80 0.80 0.80], 'GridAlpha', 0.6); catch, end
ec = [30 35 40 45 50 60 70]; dE = abs([720.64 115.07 12.94 3.9 2.48 0.55 0]) + 1e-3;
stem(ec, dE, 'filled', 'LineWidth', 3, 'Color', [0.165 0.471 0.839], 'MarkerFaceColor', [0.165 0.471 0.839], 'MarkerSize', 8);
set(gca, 'YScale', 'log'); plot([28 72], [2 2], '--', 'Color', [0.5 0.5 0.5]);
xlabel('Wavefunction cutoff (Ry), \rho cutoff = 8x'); ylabel('|E - E_{70 Ry}| (meV/atom)');
title('Production cutoff 50 Ry is within ~2.5 meV/atom of 70 Ry');
set(gca, 'FontSize', 11, 'LineWidth', 0.8);
if ~exist('out', 'dir'), mkdir('out'); end
print(fig, fullfile('out', 'stem_05_cutoff_convergence.png'), '-dpng', '-r200');
close(fig);
